/// Closed per-invocation transaction-recovery scan ceilings.
#[derive(Clone, Copy)]
struct TransactionRecoveryLimits {
    receipt_fanout_directories: u64,
    receipt_leaf_entries: u64,
    final_receipts: u64,
    receipt_stages: u64,
    head_entries: u64,
    head_stages: u64,
}

const fn transaction_recovery_limits() -> TransactionRecoveryLimits {
    TransactionRecoveryLimits {
        receipt_fanout_directories: RECEIPT_RECOVERY_MAX_FANOUT_DIRECTORIES,
        receipt_leaf_entries: RECEIPT_RECOVERY_MAX_LEAF_ENTRIES,
        final_receipts: RECEIPT_RECOVERY_MAX_FINAL_RECEIPTS,
        receipt_stages: RECEIPT_RECOVERY_MAX_REMOVABLE_STAGES,
        head_entries: HEAD_RECOVERY_MAX_ENTRIES,
        head_stages: HEAD_RECOVERY_MAX_REMOVABLE_STAGES,
    }
}

/// Closed per-pointer ancestry-verification work ceilings.
#[derive(Clone, Copy)]
struct RecoveryWorkLimits {
    ancestry_transactions: u64,
    receipt_bytes: u64,
    binding_visits: u64,
    object_verifications: u64,
    object_bytes: u64,
}

const fn accepted_recovery_limits() -> RecoveryWorkLimits {
    RecoveryWorkLimits {
        ancestry_transactions: ACCEPTED_RECOVERY_MAX_ANCESTRY_TRANSACTIONS,
        receipt_bytes: ACCEPTED_RECOVERY_MAX_RECEIPT_BYTES,
        binding_visits: ACCEPTED_RECOVERY_MAX_BINDING_VISITS,
        object_verifications: ACCEPTED_RECOVERY_MAX_OBJECT_VERIFICATIONS,
        object_bytes: ACCEPTED_RECOVERY_MAX_OBJECT_BYTES,
    }
}

/// Closed multi-head branch-recovery verification ceilings.
#[derive(Clone, Copy)]
struct BranchRecoveryLimits {
    max_requests: u64,
    per_pointer: RecoveryWorkLimits,
    union: RecoveryWorkLimits,
}

const fn branch_recovery_limits() -> BranchRecoveryLimits {
    BranchRecoveryLimits {
        max_requests: BRANCH_RECOVERY_MAX_REQUESTS,
        per_pointer: RecoveryWorkLimits {
            ancestry_transactions: BRANCH_RECOVERY_MAX_ANCESTRY_PER_POINTER,
            receipt_bytes: BRANCH_RECOVERY_MAX_RECEIPT_BYTES_PER_POINTER,
            binding_visits: BRANCH_RECOVERY_MAX_BINDING_VISITS_PER_POINTER,
            object_verifications: BRANCH_RECOVERY_MAX_OBJECT_VERIFICATIONS_PER_POINTER,
            object_bytes: BRANCH_RECOVERY_MAX_OBJECT_BYTES_PER_POINTER,
        },
        union: RecoveryWorkLimits {
            ancestry_transactions: BRANCH_RECOVERY_MAX_UNION_ANCESTRY,
            receipt_bytes: BRANCH_RECOVERY_MAX_UNION_RECEIPT_BYTES,
            binding_visits: BRANCH_RECOVERY_MAX_UNION_BINDING_VISITS,
            object_verifications: BRANCH_RECOVERY_MAX_UNION_OBJECT_VERIFICATIONS,
            object_bytes: BRANCH_RECOVERY_MAX_UNION_OBJECT_BYTES,
        },
    }
}

fn ensure_transaction_recovery_limit(value: u64, limit: u64) -> Result<(), CommitError> {
    #[cfg(test)]
    tests::record_s20_530_limit_probe(value, limit);
    if value > limit {
        return Err(txn_commit_error(TransactionErrorCode::ResourceLimit));
    }
    Ok(())
}

fn ensure_ancestry_recovery_limit(value: u64, limit: u64) -> Result<(), RecoveryAncestryError> {
    #[cfg(test)]
    tests::record_s20_530_limit_probe(value, limit);
    if value > limit {
        return Err(RecoveryAncestryError::LimitExceeded);
    }
    Ok(())
}

#[cfg(test)]
enum Cross05OwnerSignal {
    OwnerHeld,
    ReleaseOwner,
}

#[cfg(test)]
struct Cross05RecoveryHold {
    root: PathBuf,
    owner_tx: ::std::sync::mpsc::SyncSender<Cross05OwnerSignal>,
    release_rx: ::std::sync::mpsc::Receiver<Cross05OwnerSignal>,
}

#[cfg(test)]
::std::thread_local! {
    static CROSS05_RECOVERY_HOLD:
        ::std::cell::RefCell<Option<Cross05RecoveryHold>> =
        const { ::std::cell::RefCell::new(None) };
}

#[cfg(test)]
fn install_transaction_recovery_hold(
    root: &Path,
    owner_tx: ::std::sync::mpsc::SyncSender<Cross05OwnerSignal>,
    release_rx: ::std::sync::mpsc::Receiver<Cross05OwnerSignal>,
) {
    CROSS05_RECOVERY_HOLD.with(|slot| {
        let mut slot = slot.borrow_mut();
        ::core::assert!(slot.is_none());
        *slot = Some(Cross05RecoveryHold {
            root: root.to_path_buf(),
            owner_tx,
            release_rx,
        });
    });
}

#[cfg(test)]
fn hold_transaction_recovery_before_exclusive_drop(
    root: &Path,
    maintenance: &RepositoryMaintenanceGuard,
) {
    CROSS05_RECOVERY_HOLD.with(|slot| {
        let Some(hold) = slot.borrow_mut().take() else {
            return;
        };
        ::core::assert_eq!(hold.root, root);
        ::core::assert!(maintenance.is_exclusive());
        ::core::assert!(maintenance.covers(root));
        ::core::assert!(hold.owner_tx.send(Cross05OwnerSignal::OwnerHeld).is_ok());
        let release = hold.release_rx.recv().unwrap();
        ::core::assert!(::core::matches!(release, Cross05OwnerSignal::ReleaseOwner));
    });
}

/// Complete verified transaction state loaded from durable bytes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct VerifiedRevision {
    transaction_id: TransactionId,
    receipt: ImportedTransactionReceipt,
    objects: Vec<EntityObject>,
}

impl VerifiedRevision {
    /// Returns the exact verified revision identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.transaction_id
    }

    /// Returns the independently authenticated complete receipt.
    #[must_use]
    pub const fn receipt(&self) -> &ImportedTransactionReceipt {
        &self.receipt
    }

    /// Consumes the revision and returns its complete receipt.
    #[must_use]
    pub fn into_receipt(self) -> ImportedTransactionReceipt {
        self.receipt
    }

    /// Returns the registry-authorized accepted semantic root.
    #[must_use]
    pub const fn state_root(&self) -> &AcceptedStateRoot {
        &self.receipt.state_root
    }

    /// Returns the registry-authorized protected policy root.
    #[must_use]
    pub const fn policy_root(&self) -> &AcceptedPolicyRoot {
        &self.receipt.policy_root
    }

    /// Returns every exact live entity object in state-root binding order.
    #[must_use]
    pub fn objects(&self) -> &[EntityObject] {
        &self.objects
    }

    /// Returns the complete sorted non-reusable identity ledger.
    #[must_use]
    pub fn tombstoned_entities(&self) -> &[EntityId] {
        &self.receipt.transaction.record.tombstoned_entities
    }
}

/// Complete verified fixed-head state loaded from durable bytes.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct AcceptedHead {
    revision: VerifiedRevision,
}

impl AcceptedHead {
    /// Returns the exact accepted revision identity.
    #[must_use]
    pub const fn transaction_id(&self) -> TransactionId {
        self.revision.transaction_id()
    }

    /// Returns the independently authenticated complete receipt.
    #[must_use]
    pub const fn receipt(&self) -> &ImportedTransactionReceipt {
        self.revision.receipt()
    }

    /// Returns the registry-authorized accepted semantic root.
    #[must_use]
    pub const fn state_root(&self) -> &AcceptedStateRoot {
        self.revision.state_root()
    }

    /// Returns the registry-authorized protected policy root.
    #[must_use]
    pub const fn policy_root(&self) -> &AcceptedPolicyRoot {
        self.revision.policy_root()
    }

    /// Returns every exact live entity object in state-root binding order.
    #[must_use]
    pub fn objects(&self) -> &[EntityObject] {
        self.revision.objects()
    }

    /// Returns the complete sorted non-reusable identity ledger.
    #[must_use]
    pub fn tombstoned_entities(&self) -> &[EntityId] {
        self.revision.tombstoned_entities()
    }

    /// Returns the verified revision backing this accepted-head claim.
    #[must_use]
    pub const fn verified_revision(&self) -> &VerifiedRevision {
        &self.revision
    }

    /// Consumes the accepted-head wrapper and returns its verified revision.
    ///
    /// Moves the already verified receipt and objects without cloning them;
    /// this does not change the work performed when loading the head.
    #[must_use]
    pub fn into_verified_revision(self) -> VerifiedRevision {
        self.revision
    }
}

