    struct CorruptionFixturePlan {
        row_id: &'static str,
        group_id: &'static str,
        leaf_id: &'static str,
        target_role: &'static str,
        artifact_role: &'static str,
        identity_recipe: &'static str,
        path_recipe: &'static str,
        corrupter_class: &'static str,
        probe_class: &'static str,
        selector: &'static str,
        distinct_from_roles: &'static [&'static str],
    }

    impl CorruptionFixturePlan {
        #[allow(clippy::too_many_arguments)]
        const fn new(
            row_id: &'static str,
            group_id: &'static str,
            leaf_id: &'static str,
            target_role: &'static str,
            artifact_role: &'static str,
            identity_recipe: &'static str,
            path_recipe: &'static str,
            corrupter_class: &'static str,
            probe_class: &'static str,
            selector: &'static str,
            distinct_from_roles: &'static [&'static str],
        ) -> Self {
            Self {
                row_id,
                group_id,
                leaf_id,
                target_role,
                artifact_role,
                identity_recipe,
                path_recipe,
                corrupter_class,
                probe_class,
                selector,
                distinct_from_roles,
            }
        }
    }

