    fn v5_scb_record_fields(input: &[u8]) -> Vec<(u32, Vec<u8>)> {
        let mut cursor = sley_scb1::ScbValueCursor::new(input).unwrap();
        let count = usize::try_from(cursor.read_record_field_count().unwrap()).unwrap();
        let mut fields = Vec::with_capacity(count);
        for _ in 0..count {
            let tag = u32::try_from(cursor.read_uvar(32).unwrap()).unwrap();
            fields.push((tag, cursor.read_sized_payload().unwrap().to_vec()));
        }
        cursor.check_finished().unwrap();
        fields
    }

    fn v5_scb_list_elements(input: &[u8]) -> Vec<Vec<u8>> {
        let mut cursor = sley_scb1::ScbValueCursor::new(input).unwrap();
        let count = usize::try_from(cursor.read_list_count().unwrap()).unwrap();
        let mut elements = Vec::with_capacity(count);
        for _ in 0..count {
            elements.push(cursor.read_sized_payload().unwrap().to_vec());
        }
        cursor.check_finished().unwrap();
        elements
    }

    fn v5_replace_record_field(
        fields: &mut [(u32, Vec<u8>)],
        tag: u32,
        payload: Vec<u8>,
    ) {
        let field = fields
            .iter_mut()
            .find(|(candidate_tag, _)| *candidate_tag == tag)
            .expect("selected candidate record field");
        field.1 = payload;
    }

    fn v5_candidate_record_fields(candidate: &ImportedCandidate) -> Vec<(u32, Vec<u8>)> {
        let mut cursor = sley_scb1::ScbValueCursor::new(&candidate.preimage).unwrap();
        ::core::assert_eq!(cursor.read_exact_bytes(8).unwrap(), b"SLEYCAN1");
        ::core::assert_eq!(cursor.read_uvar(64).unwrap(), 1);
        let record = cursor.read_sized_payload().unwrap();
        cursor.check_finished().unwrap();
        v5_scb_record_fields(record)
    }

    fn v5_candidate_stored_bytes_from_record(record: &[u8]) -> Vec<u8> {
        let mut preimage = Vec::new();
        preimage.extend_from_slice(b"SLEYCAN1");
        preimage.extend_from_slice(&sley_scb1::encode_uvar(1));
        preimage.extend_from_slice(&sley_scb1::encode_uvar(record.len() as u64));
        preimage.extend_from_slice(record);
        let candidate_id = CandidateId::derive(&preimage);
        preimage.extend_from_slice(candidate_id.as_bytes());
        preimage
    }

    fn v5_candidate_semantic_corruption(
        candidate: &ImportedCandidate,
        selector: &str,
    ) -> Vec<u8> {
        let mut fields = v5_candidate_record_fields(candidate);
        match selector {
            "candidate_mutation_candidate_format_version" => {
                v5_replace_record_field(&mut fields, 1, sley_scb1::encode_uvar(2));
            }
            "candidate_mutation_candidate_expiry_invalid" => {
                let expiry = sley_scb1::encode_record(&[
                    (1, sley_scb1::encode_uvar(1)),
                    (2, sley_scb1::encode_uvar(0)),
                ])
                .unwrap();
                v5_replace_record_field(&mut fields, 13, expiry);
            }
            "candidate_mutation_candidate_empty_operations" => {
                v5_replace_record_field(
                    &mut fields,
                    9,
                    sley_scb1::encode_list(&[]).unwrap(),
                );
            }
            "candidate_mutation_candidate_operation_ordinal"
            | "candidate_mutation_candidate_operation_precondition_ordinal"
            | "candidate_mutation_candidate_descriptor_unknown"
            | "candidate_mutation_candidate_payload_kind"
            | "candidate_mutation_candidate_target_entity" => {
                let operations = v5_scb_list_elements(&fields[8].1);
                ::core::assert_eq!(operations.len(), 1);
                let mut operation_fields = v5_scb_record_fields(&operations[0]);
                match selector {
                    "candidate_mutation_candidate_operation_ordinal" => {
                        v5_replace_record_field(
                            &mut operation_fields,
                            1,
                            sley_scb1::encode_uvar(1),
                        );
                    }
                    "candidate_mutation_candidate_operation_precondition_ordinal" => {
                        v5_replace_record_field(
                            &mut operation_fields,
                            7,
                            sley_scb1::encode_uvar(1),
                        );
                    }
                    "candidate_mutation_candidate_descriptor_unknown" => {
                        v5_replace_record_field(
                            &mut operation_fields,
                            3,
                            sley_scb1::encode_uvar(999),
                        );
                    }
                    "candidate_mutation_candidate_payload_kind" => {
                        v5_replace_record_field(
                            &mut operation_fields,
                            3,
                            sley_scb1::encode_uvar(9),
                        );
                    }
                    "candidate_mutation_candidate_target_entity" => {
                        let replacement = [0xee_u8; 32];
                        ::core::assert_ne!(
                            candidate.record.operations[0].target_entity.as_bytes(),
                            &replacement,
                        );
                        v5_replace_record_field(
                            &mut operation_fields,
                            4,
                            replacement.to_vec(),
                        );
                    }
                    _ => unreachable!(),
                }
                let operation = sley_scb1::encode_record(&operation_fields).unwrap();
                v5_replace_record_field(
                    &mut fields,
                    9,
                    sley_scb1::encode_list(&[operation]).unwrap(),
                );
            }
            "candidate_mutation_candidate_precondition_count" => {
                v5_replace_record_field(
                    &mut fields,
                    10,
                    sley_scb1::encode_list(&[]).unwrap(),
                );
            }
            "candidate_mutation_candidate_precondition_mismatch" => {
                let exact_version = sley_scb1::encode_record(&[
                    (
                        1,
                        candidate.record.operations[0]
                            .target_entity
                            .as_bytes()
                            .to_vec(),
                    ),
                    (2, [0x91_u8; 32].to_vec()),
                ])
                .unwrap();
                let precondition = sley_scb1::encode_record(&[
                    (1, sley_scb1::encode_uvar(0)),
                    (2, sley_scb1::encode_uvar(2)),
                    (3, sley_scb1::encode_union(2, &exact_version).unwrap()),
                ])
                .unwrap();
                v5_replace_record_field(
                    &mut fields,
                    10,
                    sley_scb1::encode_list(&[precondition]).unwrap(),
                );
            }
            "candidate_mutation_candidate_validation_profile" => {
                let mut profile = fields[10].1.clone();
                profile[0] ^= 1;
                v5_replace_record_field(&mut fields, 11, profile);
            }
            selector => ::core::panic!("unsupported candidate semantic selector: {selector}"),
        }
        let record = sley_scb1::encode_record(&fields).unwrap();
        v5_candidate_stored_bytes_from_record(&record)
    }

    fn v5_candidate_corruption(
        candidate: &ImportedCandidate,
        selector: &str,
    ) -> Vec<u8> {
        match selector {
            "candidate_scb_bool_invalid" => {
                let mut alternate_record = candidate.record.clone();
                match &mut alternate_record.operations[0].payload {
                    MutationPayload::CreateEntity(EntityBodyValue::Constant(body)) => {
                        ::core::assert!(::core::matches!(
                            &body.value.data,
                            ConstData::Bool(true)
                        ));
                        body.value.data = ConstData::Bool(false);
                    }
                    payload => ::core::panic!("unexpected Bool carrier payload: {payload:?}"),
                }
                let alternate = build_candidate(&alternate_record).unwrap();
                let digest_offset = candidate.stored_bytes.len() - 32;
                let changed = candidate.stored_bytes[..digest_offset]
                    .iter()
                    .zip(&alternate.stored_bytes[..digest_offset])
                    .enumerate()
                    .filter_map(|(offset, (left, right))| (left != right).then_some(offset))
                    .collect::<Vec<_>>();
                ::core::assert_eq!(changed.len(), 1, "Bool carrier has one value byte");
                v5_reseal_candidate_byte(&candidate.stored_bytes, changed[0], 2)
            }
            "candidate_scb_utf8_invalid" => {
                let offset = v5_unique_subslice_offset(
                    &candidate.stored_bytes,
                    b"s20-530-v5-text-carrier-unique",
                );
                v5_reseal_candidate_byte(&candidate.stored_bytes, offset, 0x80)
            }
            "candidate_scb_float_non_canonical" => {
                let offset =
                    v5_unique_subslice_offset(&candidate.stored_bytes, &[0x7f, 0xc0, 0, 0]);
                v5_reseal_candidate_byte(&candidate.stored_bytes, offset + 3, 1)
            }
            "candidate_mutation_candidate_format_version"
            | "candidate_mutation_candidate_expiry_invalid"
            | "candidate_mutation_candidate_empty_operations"
            | "candidate_mutation_candidate_operation_ordinal"
            | "candidate_mutation_candidate_operation_precondition_ordinal"
            | "candidate_mutation_candidate_precondition_count"
            | "candidate_mutation_candidate_precondition_mismatch"
            | "candidate_mutation_candidate_descriptor_unknown"
            | "candidate_mutation_candidate_payload_kind"
            | "candidate_mutation_candidate_target_entity"
            | "candidate_mutation_candidate_validation_profile" => {
                v5_candidate_semantic_corruption(candidate, selector)
            }
            selector => ::core::panic!("unsupported nested candidate selector: {selector}"),
        }
    }

    fn apply_receipt_nested_candidate_corruption(
        _fixture: &Fixture,
        fixture_plan: &CorruptionFixturePlan,
        fault_path: &Path,
    ) {
        assert_cor06_receipt_nested_candidate_plan(fixture_plan);
        let receipt_bytes = fs::read(fault_path).unwrap();
        let receipt = import_transaction_receipt(&receipt_bytes).unwrap();
        let corrupted_candidate = v5_candidate_corruption(
            receipt.candidate.as_ref().expect("ordinary candidate carrier"),
            fixture_plan.selector,
        );
        let mut record = receipt.record;
        record.stored_candidate = Some(corrupted_candidate);
        let corrupted_receipt = v5_receipt_stored_bytes(&record);
        write_corruption_file(fault_path, &corrupted_receipt);
    }

    fn v5_candidate_result_record_fields(
        result: &sley_policy::ImportedCandidateResult,
    ) -> Vec<(u32, Vec<u8>)> {
        let mut cursor = sley_scb1::ScbValueCursor::new(&result.preimage).unwrap();
        ::core::assert_eq!(cursor.read_exact_bytes(8).unwrap(), b"SLEYCRS1");
        ::core::assert_eq!(cursor.read_uvar(64).unwrap(), 1);
        let record = cursor.read_sized_payload().unwrap();
        cursor.check_finished().unwrap();
        v5_scb_record_fields(record)
    }

    fn v5_candidate_result_stored_bytes_from_record(record: &[u8]) -> Vec<u8> {
        let mut preimage = Vec::new();
        preimage.extend_from_slice(b"SLEYCRS1");
        preimage.extend_from_slice(&sley_scb1::encode_uvar(1));
        preimage.extend_from_slice(&sley_scb1::encode_uvar(record.len() as u64));
        preimage.extend_from_slice(record);
        let result_id = sley_id::CandidateResultId::derive(&preimage);
        preimage.extend_from_slice(result_id.as_bytes());
        preimage
    }

    fn v5_candidate_result_set_failure(
        fields: &mut [(u32, Vec<u8>)],
        decision_tag: u32,
        failed_phase: usize,
    ) {
        v5_replace_record_field(
            fields,
            6,
            sley_scb1::encode_uvar(u64::from(decision_tag)),
        );
        let phases = v5_scb_list_elements(&fields[6].1);
        ::core::assert_eq!(phases.len(), 14);
        let phases = phases
            .into_iter()
            .enumerate()
            .map(|(index, phase)| {
                let phase_tag = index + 1;
                let mut phase_fields = v5_scb_record_fields(&phase);
                if phase_tag == failed_phase {
                    v5_replace_record_field(
                        &mut phase_fields,
                        2,
                        sley_scb1::encode_uvar(2),
                    );
                    v5_replace_record_field(
                        &mut phase_fields,
                        4,
                        sley_scb1::encode_union(
                            1,
                            &sley_scb1::encode_uvar(u64::from(decision_tag)),
                        )
                        .unwrap(),
                    );
                } else if phase_tag > failed_phase {
                    v5_replace_record_field(
                        &mut phase_fields,
                        2,
                        sley_scb1::encode_uvar(3),
                    );
                    v5_replace_record_field(
                        &mut phase_fields,
                        3,
                        sley_scb1::encode_union(0, &[]).unwrap(),
                    );
                    v5_replace_record_field(
                        &mut phase_fields,
                        4,
                        sley_scb1::encode_union(0, &[]).unwrap(),
                    );
                }
                sley_scb1::encode_record(&phase_fields).unwrap()
            })
            .collect::<Vec<_>>();
        v5_replace_record_field(fields, 7, sley_scb1::encode_list(&phases).unwrap());
    }

    fn v5_candidate_result_corruption(
        result: &sley_policy::ImportedCandidateResult,
        selector: &str,
    ) -> Vec<u8> {
        let mut fields = v5_candidate_result_record_fields(result);
        match selector {
            "candidate_result_candidate_result_format_version" => {
                v5_replace_record_field(&mut fields, 1, sley_scb1::encode_uvar(2));
            }
            "candidate_result_candidate_result_profile_invalid" => {
                let mut profile = fields[3].1.clone();
                profile[0] ^= 1;
                v5_replace_record_field(&mut fields, 4, profile);
            }
            "candidate_result_candidate_result_phase_shape" => {
                v5_replace_record_field(
                    &mut fields,
                    7,
                    sley_scb1::encode_list(&[]).unwrap(),
                );
            }
            "candidate_result_candidate_result_decision_phase_mismatch" => {
                v5_candidate_result_set_failure(&mut fields, 9, 5);
            }
            "candidate_result_candidate_result_diagnostic_invalid" => {
                let diagnostic = sley_scb1::encode_record(&[
                    (1, sley_scb1::encode_uvar(14)),
                    (2, sley_scb1::encode_uvar(1)),
                    (3, sley_scb1::encode_union(0, &[]).unwrap()),
                    (4, sley_scb1::encode_text("X").unwrap()),
                    (5, sley_scb1::encode_uvar(1)),
                    (6, sley_scb1::encode_union(0, &[]).unwrap()),
                ])
                .unwrap();
                v5_replace_record_field(
                    &mut fields,
                    8,
                    sley_scb1::encode_list(&[diagnostic]).unwrap(),
                );
            }
            "candidate_result_candidate_result_set_invalid" => {
                let duplicate = [0x55_u8; 32].to_vec();
                v5_replace_record_field(
                    &mut fields,
                    9,
                    sley_scb1::encode_list(&[duplicate.clone(), duplicate]).unwrap(),
                );
            }
            "candidate_result_candidate_result_candidate_id_shape" => {
                v5_replace_record_field(
                    &mut fields,
                    3,
                    sley_scb1::encode_union(0, &[]).unwrap(),
                );
            }
            "candidate_result_candidate_result_root_shape" => {
                v5_replace_record_field(
                    &mut fields,
                    12,
                    sley_scb1::encode_union(0, &[]).unwrap(),
                );
            }
            selector => {
                ::core::panic!("unsupported nested candidate-result selector: {selector}")
            }
        }
        let record = sley_scb1::encode_record(&fields).unwrap();
        v5_candidate_result_stored_bytes_from_record(&record)
    }

    fn apply_receipt_nested_candidate_result_corruption(
        _fixture: &Fixture,
        fixture_plan: &CorruptionFixturePlan,
        fault_path: &Path,
    ) {
        assert_cor06_receipt_nested_candidate_result_plan(fixture_plan);
        let receipt_bytes = fs::read(fault_path).unwrap();
        let receipt = import_transaction_receipt(&receipt_bytes).unwrap();
        let corrupted_result = v5_candidate_result_corruption(
            receipt
                .candidate_result
                .as_ref()
                .expect("ordinary candidate-result carrier"),
            fixture_plan.selector,
        );
        let mut record = receipt.record;
        record.stored_candidate_result = Some(corrupted_result);
        let corrupted_receipt = v5_receipt_stored_bytes(&record);
        write_corruption_file(fault_path, &corrupted_receipt);
    }

    fn v5_transaction_record_fields(
        transaction: &crate::codec::ImportedTransaction,
    ) -> Vec<(u32, Vec<u8>)> {
        let mut cursor = sley_scb1::ScbValueCursor::new(&transaction.preimage).unwrap();
        ::core::assert_eq!(cursor.read_exact_bytes(8).unwrap(), b"SLEYTXN1");
        ::core::assert_eq!(cursor.read_uvar(64).unwrap(), 1);
        let record = cursor.read_sized_payload().unwrap();
        cursor.check_finished().unwrap();
        v5_scb_record_fields(record)
    }

    fn v5_transaction_stored_bytes_from_record(
        record: &[u8],
    ) -> (Vec<u8>, TransactionId) {
        let mut preimage = Vec::new();
        preimage.extend_from_slice(b"SLEYTXN1");
        preimage.extend_from_slice(&sley_scb1::encode_uvar(1));
        preimage.extend_from_slice(&sley_scb1::encode_uvar(record.len() as u64));
        preimage.extend_from_slice(record);
        let transaction_id = TransactionId::derive(&preimage);
        preimage.extend_from_slice(transaction_id.as_bytes());
        (preimage, transaction_id)
    }

    fn v5_non_valid_candidate_result(
        result: &sley_policy::ImportedCandidateResult,
    ) -> Vec<u8> {
        let mut fields = v5_candidate_result_record_fields(result);
        v5_candidate_result_set_failure(&mut fields, 9, 6);
        v5_replace_record_field(
            &mut fields,
            12,
            sley_scb1::encode_union(0, &[]).unwrap(),
        );
        let diagnostic = sley_scb1::encode_record(&[
            (1, sley_scb1::encode_uvar(6)),
            (2, sley_scb1::encode_uvar(36_007)),
            (3, sley_scb1::encode_union(0, &[]).unwrap()),
            (
                4,
                sley_scb1::encode_text("CANDIDATE_VALIDATION_TYPE_ERROR").unwrap(),
            ),
            (5, sley_scb1::encode_uvar(1)),
            (6, sley_scb1::encode_union(0, &[]).unwrap()),
        ])
        .unwrap();
        v5_replace_record_field(
            &mut fields,
            8,
            sley_scb1::encode_list(&[diagnostic]).unwrap(),
        );
        let record = sley_scb1::encode_record(&fields).unwrap();
        let stored = v5_candidate_result_stored_bytes_from_record(&record);
        let imported = sley_policy::import_candidate_result(&stored).unwrap();
        ::core::assert_eq!(
            imported.record.decision,
            sley_policy::CandidateDecision::TypeError,
        );
        stored
    }

    fn v5_transaction_corruption(
        transaction: &crate::codec::ImportedTransaction,
        selector: &str,
    ) -> (Vec<u8>, TransactionId) {
        let mut fields = v5_transaction_record_fields(transaction);
        match selector {
            "receipt_txn_format_version" => {
                v5_replace_record_field(&mut fields, 1, sley_scb1::encode_uvar(2));
            }
            "receipt_txn_kind_invalid" => {
                v5_replace_record_field(&mut fields, 2, sley_scb1::encode_uvar(99));
            }
            "receipt_txn_parent_shape" => {
                v5_replace_record_field(
                    &mut fields,
                    4,
                    sley_scb1::encode_list(&[]).unwrap(),
                );
            }
            "receipt_txn_field_shape" => {
                let mut metadata = v5_scb_record_fields(&fields[18].1);
                v5_replace_record_field(&mut metadata, 1, sley_scb1::encode_uvar(2));
                v5_replace_record_field(
                    &mut fields,
                    19,
                    sley_scb1::encode_record(&metadata).unwrap(),
                );
            }
            "receipt_txn_changed_binding_invalid" => {
                let bindings = v5_scb_list_elements(&fields[13].1);
                ::core::assert_eq!(bindings.len(), 1);
                v5_replace_record_field(
                    &mut fields,
                    14,
                    sley_scb1::encode_list(&[bindings[0].clone(), bindings[0].clone()])
                        .unwrap(),
                );
            }
            "receipt_txn_tombstone_invalid" => {
                let duplicate = [0x63_u8; 32].to_vec();
                v5_replace_record_field(
                    &mut fields,
                    18,
                    sley_scb1::encode_list(&[duplicate.clone(), duplicate]).unwrap(),
                );
            }
            "receipt_txn_result_binding_mismatch" => {
                v5_replace_record_field(
                    &mut fields,
                    10,
                    sley_scb1::encode_union(1, &[0x71_u8; 32]).unwrap(),
                );
            }
            "receipt_txn_test_evidence_unsupported" => {
                v5_replace_record_field(
                    &mut fields,
                    16,
                    sley_scb1::encode_list(&[[0x72_u8; 32].to_vec()]).unwrap(),
                );
            }
            "receipt_txn_object_inventory_mismatch" => {
                let bindings = v5_scb_list_elements(&fields[13].1);
                ::core::assert_eq!(bindings.len(), 1);
                let mut binding = v5_scb_record_fields(&bindings[0]);
                let replacement = [0x73_u8; 32];
                ::core::assert_ne!(
                    transaction.record.changed_entity_bindings[0]
                        .postimage
                        .expect("created postimage")
                        .as_bytes(),
                    &replacement,
                );
                v5_replace_record_field(
                    &mut binding,
                    3,
                    sley_scb1::encode_union(1, &replacement).unwrap(),
                );
                let binding = sley_scb1::encode_record(&binding).unwrap();
                v5_replace_record_field(
                    &mut fields,
                    14,
                    sley_scb1::encode_list(&[binding]).unwrap(),
                );
            }
            "receipt_txn_receipt_binding_mismatch" => {
                let replacement = [0x74_u8; 32];
                ::core::assert_ne!(transaction.record.workspace_id.as_bytes(), &replacement);
                v5_replace_record_field(&mut fields, 3, replacement.to_vec());
            }
            "receipt_txn_genesis_invalid" => {
                v5_replace_record_field(&mut fields, 2, sley_scb1::encode_uvar(1));
            }
            "codec_txn_resource_limit" => {
                v5_replace_record_field(&mut fields, 16, sley_scb1::encode_uvar(65_536));
            }
            selector => ::core::panic!("unsupported nested transaction selector: {selector}"),
        }
        let record = sley_scb1::encode_record(&fields).unwrap();
        v5_transaction_stored_bytes_from_record(&record)
    }

    fn apply_receipt_nested_transaction_corruption(
        _fixture: &Fixture,
        fixture_plan: &CorruptionFixturePlan,
        fault_path: &Path,
    ) {
        assert_cor06_receipt_nested_transaction_plan(fixture_plan);
        let receipt_bytes = fs::read(fault_path).unwrap();
        let receipt = import_transaction_receipt(&receipt_bytes).unwrap();
        let mut record = receipt.record;
        if fixture_plan.selector == "receipt_txn_result_not_valid" {
            record.stored_candidate_result = Some(v5_non_valid_candidate_result(
                receipt
                    .candidate_result
                    .as_ref()
                    .expect("ordinary candidate-result carrier"),
            ));
        } else {
            let (stored_transaction, transaction_id) =
                v5_transaction_corruption(&receipt.transaction, fixture_plan.selector);
            record.stored_transaction = stored_transaction;
            record.transaction_id = transaction_id;
        }
        let corrupted_receipt = v5_receipt_stored_bytes(&record);
        write_corruption_file(fault_path, &corrupted_receipt);
    }

    fn apply_receipt_envelope_corruption(
        _fixture: &Fixture,
        fixture_plan: &CorruptionFixturePlan,
        fault_path: &Path,
    ) {
        assert_cor06_receipt_envelope_plan(fixture_plan);
        let pristine = fs::read(fault_path).unwrap();
        let bytes = match fixture_plan.selector {
            "receipt_scb_magic_invalid" => {
                let mut bytes = pristine;
                bytes[0] ^= 1;
                bytes
            }
            "receipt_scb_version_unsupported" => {
                let mut bytes = pristine;
                bytes[8] = 2;
                bytes
            }
            "receipt_scb_digest_mismatch" => {
                let mut bytes = pristine;
                *bytes.last_mut().expect("receipt digest byte") ^= 1;
                bytes
            }
            "receipt_scb_trailing_bytes" => {
                let mut bytes = pristine;
                bytes.insert(bytes.len() - 32, 0);
                bytes
            }
            "receipt_scb_varint_non_minimal" => {
                let mut bytes = Vec::with_capacity(pristine.len() + 1);
                bytes.extend_from_slice(&pristine[..8]);
                bytes.extend_from_slice(&[0x81, 0x00]);
                bytes.extend_from_slice(&pristine[9..]);
                bytes
            }
            "receipt_scb_integer_overflow" => {
                let mut bytes = Vec::with_capacity(pristine.len() + 9);
                bytes.extend_from_slice(&pristine[..8]);
                bytes.extend_from_slice(&[
                    0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02,
                ]);
                bytes.extend_from_slice(&pristine[9..]);
                bytes
            }
            "receipt_scb_length_overflow" => pristine[..31].to_vec(),
            "receipt_scb_field_missing"
            | "receipt_scb_field_unknown"
            | "receipt_scb_field_duplicate"
            | "receipt_scb_union_invalid"
            | "receipt_scb_resource_limit" => {
                let receipt = import_transaction_receipt(&pristine).unwrap();
                let mut fields = v5_receipt_record_fields(&receipt.record);
                let payload = match fixture_plan.selector {
                    "receipt_scb_field_missing" => {
                        fields.pop().expect("receipt field nine");
                        v5_manual_record(&fields)
                    }
                    "receipt_scb_field_unknown" => {
                        fields.push((10, Vec::new()));
                        v5_manual_record(&fields)
                    }
                    "receipt_scb_field_duplicate" => {
                        fields[1].0 = 1;
                        v5_manual_record(&fields)
                    }
                    "receipt_scb_union_invalid" => {
                        fields[3].1 = sley_scb1::encode_union(2, &[]).unwrap();
                        v5_manual_record(&fields)
                    }
                    "receipt_scb_resource_limit" => sley_scb1::encode_uvar(1_000_001),
                    _ => unreachable!(),
                };
                v5_receipt_stored_bytes_from_payload(&payload)
            }
            selector => ::core::panic!("unsupported receipt envelope selector: {selector}"),
        };
        write_corruption_file(fault_path, &bytes);
    }

    fn path_bound_receipt_read_injection(
        _fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<(), CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        recovery_path_read_test_hook::inject(RecoveryPathReadKind::Receipt, fault_path)
            .map_err(CommitError::Io)
    }

    fn path_bound_object_read_injection(
        _fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<(), CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        recovery_path_read_test_hook::inject(RecoveryPathReadKind::Object, fault_path)
            .map_err(StoreError::io)
            .map_err(CommitError::Store)
    }

    fn object_store_read_error(
        fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<Vec<u8>, CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        let transaction_id =
            decode_head(&fs::read(fixture.repository.head_path()).unwrap()).unwrap();
        let receipt_bytes =
            fs::read(corruption_receipt_path(fixture.path(), transaction_id)).unwrap();
        let receipt = import_transaction_receipt(&receipt_bytes).unwrap();
        let object_store = ObjectStore::new(fixture.path());
        let object_id = receipt
            .record
            .object_manifest
            .iter()
            .map(|entry| entry.object_id)
            .find(|object_id| object_store.object_path(*object_id) == fault_path)
            .expect("fault object is present in the accepted receipt manifest");
        let verifier = super::entity_verifier(receipt.state_root.record.schema_epoch_id);
        object_store
            .read(object_id, &verifier)
            .map_err(CommitError::Store)
    }

    fn import_receipt_then_verify_revision(
        fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<(), CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        let receipt_bytes = fs::read(fault_path).map_err(CommitError::Io)?;
        let receipt = import_transaction_receipt(&receipt_bytes)?;
        fixture
            .repository
            .verify_transaction_relationship(&receipt)?;
        let objects = fixture.repository.load_objects(&receipt.state_root)?;
        verify_manifest_lengths(&receipt.record.object_manifest, &objects)
    }

    fn verify_absent_revision_receipt(
        _fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<(), CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        super::TransactionRepository::read_receipt_at(
            fixture_observation.target_identity,
            fault_path,
        )
        .map(|_| ())
    }

    fn decode_accepted_pointer_error(
        _fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<TransactionId, CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        let bytes = fs::read(fault_path).map_err(CommitError::Io)?;
        decode_head(&bytes)
    }

    fn import_transaction_receipt_error(
        _fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        fault_path: &Path,
    ) -> Result<(), CommitError> {
        ::core::assert_eq!(fault_path, fixture_observation.fault_path);
        let bytes = fs::read(fault_path).map_err(CommitError::Io)?;
        import_transaction_receipt(&bytes)
            .map(|_| ())
            .map_err(CommitError::Codec)
    }

    fn probe_untargeted_corruption_control(
        _fixture: &Fixture,
        fixture_observation: &CorruptionFixtureObservation,
        control_path: &Path,
    ) -> Result<(), CommitError> {
        ::core::assert_eq!(control_path, fixture_observation.control_path);
        let read_kind = if fixture_observation.control_is_object {
            RecoveryPathReadKind::Object
        } else {
            RecoveryPathReadKind::Receipt
        };
        recovery_path_read_test_hook::inject(read_kind, control_path)
            .map_err(CommitError::Io)?;
        let bytes = fs::read(control_path).map_err(CommitError::Io)?;
        if fixture_observation.control_is_object {
            Ok(())
        } else {
            import_transaction_receipt(&bytes)
                .map(|_| ())
                .map_err(CommitError::Codec)
        }
    }

