        ::core::assert_eq!(("loser_probe_code", loser_probe_error.code()), ("loser_probe_code", "RECOVERY_RECEIPT_INCOMPLETE"));
        let owner_tree_before_snapshot = crate::repository::tests::exact_tree_snapshot(owner_root);
