    #[test]
    #[ignore = "explicit S20-390 conformance fixture refresh helper"]
    fn emit_transaction_receipt_vectors_for_fixture_refresh() {
        let fixture = Fixture::with_mutation_classes("emit", &[MutationClass::CreateEntity]);
        let genesis = fixture.repository.accepted_head().unwrap();
        emit_vector("GENESIS", genesis.receipt());
        fixture.repository.commit(fixture.input()).unwrap();
        let ordinary = fixture.repository.accepted_head().unwrap();
        emit_vector("ORDINARY", ordinary.receipt());

        // A commit whose program carries a judged operation, so the corpus
        // covers semantic profile 2 (transaction model revision 2).
        let extended = Fixture::new("emit-extended");
        let head = extended.repository.accepted_head().unwrap();
        let candidate = program_candidate_for(
            head.state_root().record.workspace_id,
            extended.principal_id,
            extended.genesis_transaction_id,
            head.state_root(),
            head.policy_root(),
            0x5c,
        );
        extended
            .repository
            .commit(CommitInput::new(
                extended.genesis_transaction_id,
                &candidate.stored_bytes,
                extended.principal_id,
                &[],
                NOW,
                CandidateValidationLimits::full_v1(),
            ))
            .unwrap();
        let committed = extended.repository.accepted_head().unwrap();
        emit_vector("ORDINARY_EXTENDED", committed.receipt());
    }

    fn emit_vector(kind: &str, receipt: &ImportedTransactionReceipt) {
        println!(
            "TXN_VECTOR|{kind}|{}|{}|{}|{}|{}",
            hex(receipt.transaction.transaction_id.as_bytes()),
            hex(receipt.receipt_id.as_bytes()),
            hex(&receipt.transaction.stored_bytes),
            hex(&receipt.stored_bytes),
            manifest_descriptor(&receipt.record.object_manifest),
        );
        if kind == "GENESIS" {
            // A trusted genesis performs no analysis, so the extended triple
            // is not a genesis wire state (transaction model revision 3). Mint
            // the bytes below validation so the corpus proves both decoders
            // refuse them with TXN_FIELD_SHAPE.
            let mut forged = receipt.transaction.record.clone();
            forged.commit_metadata = CommitMetadata::extended_operations_v1();
            let payload = encode_transaction_record(&forged).unwrap();
            let preimage = encode_envelope(TRANSACTION_MAGIC, &payload).unwrap();
            let forged_id = TransactionId::derive(&preimage);
            let stored = append_digest(&preimage, forged_id.as_bytes()).unwrap();
            println!(
                "TXN_REJECT|genesis-extended-profile|TXN_FIELD_SHAPE|{}|{}",
                hex(&stored),
                manifest_descriptor(&receipt.record.object_manifest),
            );
        }
        if kind == "ORDINARY" {
            let mut record = receipt.record.clone();
            record.object_manifest[0].stored_length = record.object_manifest[0]
                .stored_length
                .checked_add(1)
                .unwrap();
            let bad = build_transaction_receipt(&record).unwrap();
            println!(
                "TXN_REJECT|manifest-stored-length|TXN_OBJECT_INVENTORY_MISMATCH|{}|{}",
                hex(&bad.stored_bytes),
                manifest_descriptor(&receipt.record.object_manifest),
            );
        }
    }

    fn manifest_descriptor(manifest: &[ObjectManifestEntry]) -> String {
        manifest
            .iter()
            .map(|entry| {
                format!(
                    "{}:{}",
                    hex(entry.object_id.as_bytes()),
                    entry.stored_length
                )
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    fn snapshot_tree(root: &Path) -> Vec<PathBuf> {
        fn visit(root: &Path, current: &Path, output: &mut Vec<PathBuf>) {
            let mut entries = fs::read_dir(current)
                .unwrap()
                .map(|entry| entry.unwrap())
                .collect::<Vec<_>>();
            entries.sort_by_key(std::fs::DirEntry::file_name);
            for entry in entries {
                let path = entry.path();
                output.push(path.strip_prefix(root).unwrap().to_path_buf());
                if entry.file_type().unwrap().is_dir() {
                    visit(root, &path, output);
                }
            }
        }

        let mut output = Vec::new();
        visit(root, root, &mut output);
        output
    }

    fn hex(bytes: &[u8]) -> String {
        use fmt::Write as _;

        let mut output = String::with_capacity(bytes.len() * 2);
        for byte in bytes {
            write!(&mut output, "{byte:02x}").unwrap();
        }
        output
    }
